def primitive_arrays(container, primitive):
    """Return (positions, uvs_or_None, attr_map, indices_or_None).

    ``attr_map`` holds every *other* per-vertex attribute keyed by its glTF
    attribute name so the DSU remap can carry it alongside POSITION/UV.
    """
    attributes = primitive["attributes"]
    positions = decode_accessor(container, attributes["POSITION"])
    uvs = None
    if "TEXCOORD_0" in attributes:
        uvs = decode_accessor(container, attributes["TEXCOORD_0"])

    attr_map = {}
    for name, accessor_index in attributes.items():
        if name in ("POSITION", "TEXCOORD_0"):
            continue
