class _BlobBuilder:
    def __init__(self):
        self.pieces = []
        self.length = 0

    def add(self, blob):
        offset = self.length
        padding = (-offset) % 4
        if padding:
            self.pieces.append(b"\x00" * padding)
            self.length += padding
        self.pieces.append(blob)
        self.length += len(blob)
        return offset

    def finish(self):
        padding = (-self.length) % 4
        if padding:
            self.pieces.append(b"\x00" * padding)
            self.length += padding
        return b"".join(self.pieces)


